    softDeleteListing(listing.id);
    expect(() => setStatus(listing.id, 'deleted')).toThrow(
      `cannot transition from deleted to deleted for listing ${listing.id}`
    );
    expect(getListingById(listing.id)?.status).toBe('deleted');
  });

  it('blocks expired -> fulfilled', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
