export async function setStatus(id: number, newStatus: 'active' | 'fulfilled' | 'deleted'): Promise<void> {
  const currentStatus = await getListingById(id);

  if (!currentStatus) {
    throw new Error(`Listing ${id} not found`);
  }

  // Valid transitions: active → fulfilled/deleted, fulfilled → deleted
  const validTransitions: Record<string, Array<'active' | 'fulfilled' | 'deleted'>> = {
    active: ['fulfilled', 'deleted'],
    fulfilled: ['deleted'],
    deleted: [], // No transitions from deleted
    expired: [] // No transitions from expired
  };

  if (!validTransitions[currentStatus.status].includes(newStatus)) {
    throw new Error(`cannot transition from ${currentStatus.status} to ${newStatus} for listing ${id}`);
  }

  // Update the listing status
  await db
    .update(listings)
    .set({ status: newStatus })
    .where(eq(listings.id, id))
    .run();
}

