  const currentListing = await db.select({ status: listings.status }).from(listings).where(eq(listings.id, id));
  if (!currentListing.length) throw new Error(`Listing ${id} not found`);
  const [currentStatus] = currentListing;

  // Validate transition
  if ((currentStatus.status === 'active' && status !== 'fulfilled' && status !== 'deleted') ||
      (currentStatus.status === 'fulfilled' && status !== 'deleted')) {
    throw new Error(`Invalid transition for listing ${id}: ${currentStatus.status} → ${status}`);
  }

