        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status: 'active',
        expiresAt: later + 30 * 24 * 3600 * 1000,
        createdAt: later,
        updatedAt: later,
      })
      .run();
    // A listing from a different user should never show up.
    db.insert(listings)
      .values({
        serverId: '200',
        userId: 'u2',
        username: 'bob',
        intent: 'have',
        accepts: 'cash',
        game: 'mtg',
