        quantity: 1,
        notes: null,
        status: 'active',
        expiresAt: later + 30 * 24 * 3600 * 1000,
        createdAt: later,
        updatedAt: later,
      })
      .run();

    const rows = activeListingsForUser('200', 'u1');
    expect(rows.map((r) => r.cardName)).toEqual(['Card B', 'Card A']);
  });

  it('respects the limit parameter', () => {
    seedServer();
