        cardName: `Card ${i}`,
        cardNameNormalized: `card ${i}`,
        intent: 'have' as const,
        accepts: 'cash' as const,
      })),
    );
    expect(activeListingsForUser('200', 'u1', 2)).toHaveLength(2);
  });
});

